Repair the complete source below and return a corrected complete TypeScript source file with the same public API.

`skuText` is a comma-separated list. Trim each token, discard empty tokens, and remove exact duplicates while preserving first occurrence order. At least one SKU is required. `fromStep` and `toStep` must be safe integers with `fromStep <= toStep`. Every movement must have a requested SKU, a safe-integer step, a non-blank ID, and a finite integer delta; otherwise throw `RangeError` before producing a result.

Starting quantities include movements before `fromStep`. Ending quantities include movements through `toStep`, inclusive. The returned `movements` includes movements in the inclusive range, ordered by ascending step with input order breaking ties. Balances include every requested SKU, including zero balances. The function must not mutate the input array or movement objects, and returned movements must be copies.

```typescript
export interface StockMovement {
  readonly id: string;
  readonly sku: string;
  readonly step: number;
  readonly delta: number;
}

export interface StockSummary {
  readonly skus: string[];
  readonly fromStep: number;
  readonly toStep: number;
  readonly starting: Record<string, number>;
  readonly ending: Record<string, number>;
  readonly movements: StockMovement[];
}

export function summarizeStock(
  skuText: string,
  fromStep: number,
  toStep: number,
  movements: readonly StockMovement[]
): StockSummary {
  const skus = [...new Set(skuText.split(",").map((sku) => sku.trim()).filter(Boolean))];
  if (skus.length === 0) throw new RangeError("At least one SKU is required");
  if (!Number.isSafeInteger(fromStep) || !Number.isSafeInteger(toStep) || fromStep > toStep) {
    throw new RangeError("Invalid step range");
  }
  const requested = new Set(skus);
  movements.forEach((movement) => {
    if (!requested.has(movement.sku) || !Number.isSafeInteger(movement.step) ||
        !Number.isFinite(movement.delta) || !Number.isInteger(movement.delta) ||
        movement.id.trim().length === 0) {
      throw new RangeError("Invalid movement");
    }
  });

  const starting: Record<string, number> = Object.fromEntries(skus.map((sku) => [sku, 0]));
  const ending: Record<string, number> = Object.fromEntries(skus.map((sku) => [sku, 0]));
  const beforeEnd = (step: number): boolean => step < toStep;

  movements.forEach((movement) => {
    if (movement.step < fromStep) starting[movement.sku] += movement.delta;
    if (beforeEnd(movement.step)) ending[movement.sku] += movement.delta;
  });

  const selected = movements
    .map((movement, index) => ({ movement, index }))
    .filter(({ movement }) => movement.step >= fromStep && beforeEnd(movement.step))
    .sort((a, b) => a.movement.step - b.movement.step || a.index - b.index)
    .map(({ movement }) => ({ ...movement }));

  return { skus: [...skus], fromStep, toStep, starting, ending, movements: selected };
}
