import { StockMovement, summarizeStock } from "./solution";

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function deepEqual(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) throw new Error(`${message}: ${JSON.stringify(actual)}`);
}
function throwsRange(fn: () => unknown, message: string): void {
  let caught: unknown;
  try { fn(); } catch (error) { caught = error; }
  assert(caught instanceof RangeError, message);
}

const movements: StockMovement[] = [
  { id: "pre-a", sku: "A", step: 0, delta: 5 },
  { id: "at-from-b", sku: "B", step: 1, delta: 2 },
  { id: "tie-first", sku: "A", step: 2, delta: 3 },
  { id: "tie-second", sku: "B", step: 2, delta: -1 },
  { id: "at-to", sku: "A", step: 3, delta: 4 },
  { id: "after", sku: "A", step: 4, delta: 100 }
];
const before = JSON.stringify(movements);
const summary = summarizeStock(" A, B, A, , C ", 1, 3, movements);
deepEqual(summary.skus, ["A", "B", "C"], "SKUs trimmed, empties discarded, duplicates removed");
assert(summary.fromStep === 1 && summary.toStep === 3, "range retained");
deepEqual(summary.starting, { A: 5, B: 0, C: 0 }, "starting includes only movements before fromStep and all requested SKUs");
deepEqual(summary.ending, { A: 12, B: 1, C: 0 }, "ending includes movements through toStep inclusively");
deepEqual(summary.movements.map((movement) => movement.id), ["at-from-b", "tie-first", "tie-second", "at-to"], "selected movements are inclusive and stably sorted");
assert(JSON.stringify(movements) === before, "input is not mutated or reordered");
assert(summary.movements[0] !== movements[1], "returned movements are copies");
(summary.movements[0] as { delta: number }).delta = 999;
assert(movements[1].delta === 2, "returned movement mutation does not affect input");

const boundary = summarizeStock("X", Number.MAX_SAFE_INTEGER, Number.MAX_SAFE_INTEGER, [
  { id: "max", sku: "X", step: Number.MAX_SAFE_INTEGER, delta: 1 }
]);
deepEqual(boundary.starting, { X: 0 }, "safe integer boundary starting balance");
deepEqual(boundary.ending, { X: 1 }, "safe integer boundary is included");
deepEqual(boundary.movements.map((movement) => movement.id), ["max"], "single-step inclusive range");

throwsRange(() => summarizeStock(" , \t,", 0, 1, []), "at least one SKU required");
for (const range of [[1.5, 2], [0, Infinity], [2, 1], [Number.MAX_SAFE_INTEGER + 1, Number.MAX_SAFE_INTEGER + 1]] as const) {
  throwsRange(() => summarizeStock("A", range[0], range[1], []), "invalid range rejected");
}
const invalidMovements: StockMovement[] = [
  { id: "x", sku: "OTHER", step: 0, delta: 1 },
  { id: "x", sku: "A", step: 1.5, delta: 1 },
  { id: "x", sku: "A", step: Number.MAX_SAFE_INTEGER + 1, delta: 1 },
  { id: " ", sku: "A", step: 0, delta: 1 },
  { id: "x", sku: "A", step: 0, delta: 1.5 },
  { id: "x", sku: "A", step: 0, delta: Infinity }
];
for (const movement of invalidMovements) {
  const input = [movement];
  const unchanged = JSON.stringify(input);
  throwsRange(() => summarizeStock("A", 0, 1, input), "invalid movement rejected");
  assert(JSON.stringify(input) === unchanged, "invalid movement input remains unchanged");
}

